import{_ as t,c as n,o,a5 as d}from"./chunks/framework.BmNIwhaK.js";const p=JSON.parse('{"title":"SyncAdmin: AI連携に最適化されたVue 3バックオフィスフレームワーク","description":"Vue 3、Vite、TypeScriptをベースに構築されたインテリジェントな管理ダッシュボードテンプレートです。AIエージェントのモニタリング、動的なデータ可視化、きめ細かな権限制御を通じて、エンタープライズシステムの構築を支援します。","frontmatter":{"title":"SyncAdmin: AI連携に最適化されたVue 3バックオフィスフレームワーク","description":"Vue 3、Vite、TypeScriptをベースに構築されたインテリジェントな管理ダッシュボードテンプレートです。AIエージェントのモニタリング、動的なデータ可視化、きめ細かな権限制御を通じて、エンタープライズシステムの構築を支援します。","head":[["meta",{"name":"keywords","content":"SyncAdmin, Vue 3, Vite, TypeScript, 管理システムテンプレート, バックオフィス開発, 管理ダッシュボード, フロントエンド開発, AIダッシュボード, エンタープライズシステム, Pinia, 多言語対応, 権限制御, テーマカスタマイズ, UIフレームワーク, ERPシステム, CRMシステム, データ可視化, エムパシー, SyncSeries"}],["meta",{"property":"og:title","content":"SyncAdmin: AI連携に最適化されたVue 3バックオフィスフレームワーク"}],["meta",{"property":"og:description","content":"Vue 3、Vite、TypeScriptをベースに構築されたインテリジェントな管理ダッシュボードテンプレートです。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncadmin/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/syncadmin/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncadmin/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncadmin/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncadmin/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncadmin/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncAdmin: AI連携に最適化されたVue 3バックオフィスフレームワーク | Empasy Docs"}],["meta",{"property":"og:description","content":"Vue 3、Vite、TypeScriptをベースに構築されたインテリジェントな管理ダッシュボードテンプレートです。AIエージェントのモニタリング、動的なデータ可視化、きめ細かな権限制御を通じて、エンタープライズシステムの構築を支援します。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncadmin/"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncAdmin: AI連携に最適化されたVue 3バックオフィスフレームワーク | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Vue 3、Vite、TypeScriptをベースに構築されたインテリジェントな管理ダッシュボードテンプレートです。AIエージェントのモニタリング、動的なデータ可視化、きめ細かな権限制御を通じて、エンタープライズシステムの構築を支援します。"}]],"order":1,"dir":{"order":3}},"headers":[],"relativePath":"ja/syncadmin/index.md","filePath":"ja/syncadmin/index.md","lastUpdated":1795293539000}'),c={name:"ja/syncadmin/index.md"};function s(i,e,a,r,l,y){return o(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="syncadmin-インテリジェント・バックオフィスシステム向けフロントエンド標準-アーカイブ" tabindex="-1">SyncAdmin: インテリジェント・バックオフィスシステム向けフロントエンド標準（アーカイブ） <a class="header-anchor" href="#syncadmin-インテリジェント・バックオフィスシステム向けフロントエンド標準-アーカイブ" aria-label="Permalink to “SyncAdmin: インテリジェント・バックオフィスシステム向けフロントエンド標準（アーカイブ）”">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>全社フロントエンド標準の統合に関するご案内</strong>: <code>SyncAdmin</code>の設計資産およびコンポーネント体系は、現在SyncSeries 11大エンタープライズ製品群（<code>SyncVerse</code>、<code>SyncInsight</code>、<code>SyncLLM</code>、<code>SyncAPIM</code>、<code>SyncWatch</code>、<code>SyncBoot</code>、<code>SyncCMS</code>、<code>SyncShop</code>、<code>SyncOps</code>、<code>SyncETA</code>、<code>SyncCrawl</code>）の<strong><code>admin/</code>（Vue 3 + Vben Admin + DB単一ソース動的ルーティング）</strong>標準フロントエンドアーキテクチャとして全面的に組み込まれました。</p></div><p>SyncAdminは、Vue 3、Vite、TypeScriptをベースに設計されたエンタープライズ管理システム向けフロントエンド標準です。単なるデータCRUDインターフェースにとどまらず、SyncSeriesの11大AIエージェント（<code>SyncVerse</code>、<code>SyncInsight</code>、<code>SyncLLM</code>、<code>SyncAPIM</code>、<code>SyncWatch</code>、<code>SyncBoot</code>、<code>SyncCMS</code>、<code>SyncShop</code>、<code>SyncOps</code>、<code>SyncETA</code>、<code>SyncCrawl</code>）と有機的に連携し、システムの状態をモニタリングして制御できるインテリジェントなダッシュボード環境を提供します。</p><h2 id="_1-aiフレンドリーなフロントエンドアーキテクチャ" tabindex="-1">1. AIフレンドリーなフロントエンドアーキテクチャ <a class="header-anchor" href="#_1-aiフレンドリーなフロントエンドアーキテクチャ" aria-label="Permalink to “1. AIフレンドリーなフロントエンドアーキテクチャ”">​</a></h2><p>モダンなWeb技術スタックをベースに、データ駆動型の意思決定とAIモデル連携に最適化された構造を備えています。</p><ul><li><strong>モダンな技術スタック</strong>: Vue 3（Composition API）、Vite、Piniaをベースとした高速かつ軽量なレンダリング性能により、大量のログデータやAI分析結果を遅延なく画面に表示します。</li><li><strong>動的UI構成</strong>: データ構造が変更された場合やAIエージェントが新しい形式の分析結果を返却した場合でも、柔軟に応答してレイアウトを構成できる再利用可能なコンポーネントを内蔵しています。</li><li><strong>モノレポベースの管理</strong>: PnpmおよびTurboRepoを活用し、大規模プロジェクトや複数のAIサービスが統合された複雑なシステムのコードを効率的に管理します。</li></ul><h2 id="_2-コア運用・管理機能" tabindex="-1">2. コア運用・管理機能 <a class="header-anchor" href="#_2-コア運用・管理機能" aria-label="Permalink to “2. コア運用・管理機能”">​</a></h2><p>エンタープライズ環境で必須となる管理機能を標準搭載し、開発スピードを向上させます。</p><ul><li><strong>インテリジェントな権限制御およびDB動的ルーティング</strong>: 単なるページアクセス制御にとどまらず、データベース（<code>sys_permission</code>、<code>sys_role_permission</code>）を単一ソース（Single Source of Truth）とする<code>PermissionModeEnum.BACK</code>動的ルーティングおよびボタン単位のきめ細かな権限管理（RBAC）を標準サポートしています。</li><li><strong>Zero-Mock実データ連携</strong>: ハードコードされたダミーデータを使用せず、バックエンドの全社標準Canonical URL（<code>/api/v1/{product}/...</code>）と1対1で透過的に連携し、高水準な標準コンポーネント（<code>BasicTable</code>、<code>BasicModal</code>、<code>BasicForm</code>、<code>BasicDrawer</code>）を通じて一貫性のあるエンタープライズUIを提供します。</li><li><strong>多言語およびテーマ対応</strong>: 国際化（i18n）モジュールを通じて多言語環境を標準サポートしており、企業のブランドガイドラインに合わせたテーマカスタマイズやダークモードをシームレスに提供します。</li></ul><h2 id="_3-導入および活用領域" tabindex="-1">3. 導入および活用領域 <a class="header-anchor" href="#_3-導入および活用領域" aria-label="Permalink to “3. 導入および活用領域”">​</a></h2><p>SyncAdminは社内システムの構築に必要なすべてのUI資産を統合して提供するため、多様なB2Bソリューションの基盤となります。</p><ul><li><strong>統合管制ダッシュボード</strong>: AIエージェントの活動ログ、ステータス、データ収集状況をリアルタイムに可視化する管制センターとしての役割を担います。</li><li><strong>エンタープライズコアソリューション</strong>: ERP、CRM、人事管理など、複雑なビジネスロジックや多数の入力フォームを必要とするシステムの開発期間を大幅に短縮します。</li><li><strong>データ分析画面</strong>: 多様なUIフレームワーク（Ant Design Vueなど）およびチャートライブラリをサポートしており、データを直感的に把握できるレポート画面を容易に構成できます。</li></ul><hr><h2 id="_4-全社11大製品群フロントエンド-admin-標準マッピング状況" tabindex="-1">4. 全社11大製品群フロントエンド（<code>admin/</code>）標準マッピング状況 <a class="header-anchor" href="#_4-全社11大製品群フロントエンド-admin-標準マッピング状況" aria-label="Permalink to “4. 全社11大製品群フロントエンド（admin/）標準マッピング状況”">​</a></h2><p>現在、<code>SyncAdmin</code>アーキテクチャが組み込まれている11大エンタープライズ製品群のフロントエンドパッケージおよび動的権限APIマッピング仕様は以下のとおりです。</p><table tabindex="0"><thead><tr><th style="text-align:left;">製品群</th><th style="text-align:left;">フロントエンドパッケージ名（<code>package.json</code>）</th><th style="text-align:center;">ルーティングモード</th><th style="text-align:left;">動的メニュー・権限認可Canonical API</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncVerse</strong></td><td style="text-align:left;"><code>@empasy/sync-verse-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/verse/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncInsight</strong></td><td style="text-align:left;"><code>@empasy/sync-insight-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/insight/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncLLM</strong></td><td style="text-align:left;"><code>@empasy/sync-llm-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/llm/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncAPIM</strong></td><td style="text-align:left;"><code>@empasy/sync-apim-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/apim/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncWatch</strong></td><td style="text-align:left;"><code>@empasy/sync-watch-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/watch/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncBoot</strong></td><td style="text-align:left;"><code>@empasy/sync-boot-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/boot/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncCMS</strong></td><td style="text-align:left;"><code>@empasy/sync-cms-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/cms/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncShop</strong></td><td style="text-align:left;"><code>@empasy/sync-shop-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/shop/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncOps</strong></td><td style="text-align:left;"><code>@empasy/sync-ops-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/ops/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncETA</strong></td><td style="text-align:left;"><code>@empasy/sync-eta-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/eta/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncCrawl</strong></td><td style="text-align:left;"><code>@empasy/sync-crawl-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/crawl/sys/permission/getUserPermissionByToken</code></td></tr></tbody></table>',16)])])}const g=t(c,[["render",s]]);export{p as __pageData,g as default};
